const items = $input.all();
if (items.length !== 1) throw new Error('Expected exactly one input item; no search sent.');
const input = items[0].json;
if (input.allowLiveRequest !== true) throw new Error('Live search is off. Review pricing and README, then set allowLiveRequest to boolean true for one manual execution.');
if (typeof input.query !== 'string') throw new Error('query must be text.');
const query = input.query.trim();
if (!query || Array.from(query).length > 1000) throw new Error('query must contain 1–1000 characters.');
return [{json: {query, k: 5, filters: {commercial: true, orientation: 'landscape'}, experiment: 'lig128_n8n_search_v1'}}];

const items = $input.all();
if (items.length !== 1) throw new Error('Unexpected response item count.');
const response = items[0].json;
if (typeof response.query_id !== 'string' || !Array.isArray(response.results)) throw new Error('Unexpected Lightdrift response envelope; inspect execution before rerunning.');
return [{json: {
  query_id: response.query_id,
  result_count: response.results.length,
  review_status: 'Human source and license review required before use',
  candidates: response.results.map((asset) => ({
    asset_id: asset.asset_id ?? null,
    title: asset.title ?? null,
    score: asset.score ?? null,
    source: asset.source ?? null,
    width: asset.width ?? null,
    height: asset.height ?? null,
    file: asset.file ?? null,
    thumb: asset.thumb ?? null,
    source_page: asset.rights?.provenance_url ?? null,
    rights: asset.rights ?? null
  })),
  response
}}];
